ALTER TABLE "organization_purge_manifest_item" ADD CONSTRAINT "organization_purge_manifest_item_claim_check" CHECK (("organization_purge_manifest_item"."status"::text = 'processing' and "organization_purge_manifest_item"."claim_token" is not null and "organization_purge_manifest_item"."claimed_at" is not null) or ("organization_purge_manifest_item"."status"::text <> 'processing' and "organization_purge_manifest_item"."claim_token" is null and "organization_purge_manifest_item"."claimed_at" is null));
